class Solution {
    private int best = Integer.MIN_VALUE;

    public int maxPathSum(TreeNode root) {
        dfsAll(root);
        return best;
    }

    private void dfsAll(TreeNode node) {
        if (node == null) return;
        int left = Math.max(0, down(node.left));
        int right = Math.max(0, down(node.right));
        best = Math.max(best, node.val + left + right);   // 完整路径
        dfsAll(node.left);
        dfsAll(node.right);
    }

    // 只能选一条边往下，因为路径不能分叉
    private int down(TreeNode node) {
        if (node == null) return 0;
        int child = Math.max(0, Math.max(down(node.left), down(node.right)));
        return node.val + child;
    }
}

class Solution {
    public int maxPathSum(TreeNode root) {
        int[] best = new int[] { Integer.MIN_VALUE };   // 数组当输出参数，无状态残留
        gain(root, best);
        return best[0];
    }

    // 返回从 node 往下单边走的可得最大和
    private int gain(TreeNode node, int[] best) {
        if (node == null) return 0;

        int left  = Math.max(0, gain(node.left, best));    // 负贡献砍掉
        int right = Math.max(0, gain(node.right, best));

        // 完整路径：左右都要
        best[0] = Math.max(best[0], node.val + left + right);

        // 往上延伸只能选一边
        return node.val + Math.max(left, right);
    }
}

import java.util.*;

class Solution {
    public int maxPathSum(TreeNode root) {
        if (root == null) return 0;

        Map<TreeNode, Integer> gain = new HashMap<>();
        Deque<TreeNode> stack = new ArrayDeque<>();
        List<TreeNode> order = new ArrayList<>();
        stack.push(root);

        // 根右左顺序入 order，这样倒着遍历就是孩子的贡献已算好
        while (!stack.isEmpty()) {
            TreeNode node = stack.pop();
            order.add(node);
            if (node.left != null) stack.push(node.left);
            if (node.right != null) stack.push(node.right);
        }

        int best = Integer.MIN_VALUE;
        for (TreeNode node : order) {
            int left  = Math.max(0, gain.getOrDefault(node.left, 0));
            int right = Math.max(0, gain.getOrDefault(node.right, 0));

            best = Math.max(best, node.val + left + right);
            gain.put(node, node.val + Math.max(left, right));
        }
        return best;
    }
}
